sparql:
PREFIX vol: <https://w3id.org/odi/volunteering#>
PREFIX ex: <https://example.org/volunteering-data/>
SELECT ?opportunity ?title ?organisation WHERE {
  ?opportunity a vol:VolunteeringOpportunity ;
    vol:supportsCause ex:environment ;
    vol:title ?title ;
    vol:offeredBy ?organisation .
}
ORDER BY ?title

PREFIX vol: <https://w3id.org/odi/volunteering#>
SELECT ?opportunity ?session ?start WHERE {
  ?opportunity vol:hasSession ?session .
  ?session vol:hasLocation ?location ;
    vol:startDateTime ?start .
  ?location a vol:OnlineLocation .
}
ORDER BY ?start

PREFIX vol: <https://w3id.org/odi/volunteering#>
SELECT ?volunteer ?role ?skill WHERE {
  ?volunteer a vol:Volunteer ;
    vol:hasSkill ?skill .
  ?role vol:requiresSkill ?skill .
}
ORDER BY ?volunteer ?role
